package vn.svframe.svframemmo;
import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.*;import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;import vn.svframe.svframelib.SVFrameLib;import vn.svframe.svframelib.api.event.PlayerAttackEvent;import vn.svframe.svframelib.fabric.runtime.RpgProfileRegistry;import vn.svframe.svframemmo.config.*;import vn.svframe.svframemmo.manager.*;import vn.svframe.svframemmo.player.ResourceRegenRuntime;import vn.svframe.svframemmo.skill.SVFrameMMOSkillBootstrap;import java.util.logging.*;
public final class SVFrameMMO implements ModInitializer {public static final String ID="svframemmo";private static final Logger LOG=Logger.getLogger("SVFrameMMO");private static final PlayerDataManager PLAYER_DATA=new PlayerDataManager();private static final ClassManager CLASSES=new ClassManager();private static final AttributeManager ATTRIBUTES=new AttributeManager();private static final ResourceRegenRuntime REGEN=new ResourceRegenRuntime();private static SVFrameMMOConfig config;private static long tick;private static AutoCloseable profileRegistration;
public void onInitialize(){try{DefaultFiles.ensure();config=SVFrameMMOConfig.load(DefaultFiles.ROOT.resolve("config.yml"));CLASSES.reload(DefaultFiles.ROOT.resolve("classes"));ATTRIBUTES.reload(DefaultFiles.ROOT.resolve("attributes"));}catch(Exception e){throw new IllegalStateException("Could not initialize SVFrameMMO defaults",e);}SVFrameLib.bootstrap();try{SVFrameMMOSkillBootstrap.register(DefaultFiles.ROOT.resolve("skills"));}catch(Exception e){throw new IllegalStateException("Could not register SVFrameMMO skill integration",e);}profileRegistration=RpgProfileRegistry.register(id->PLAYER_DATA.get(id).snapshot());SVFrameLib.inst().setClassModule(d->PLAYER_DATA.get(d.getUniqueId()).getClassId());SVFrameLib.inst().setLevelModule(d->PLAYER_DATA.get(d.getUniqueId()).getLevel());SVFrameLib.inst().setManaModule(new vn.svframe.svframelib.rpg.ManaModule(){public double getMana(vn.svframe.svframelib.api.player.MMOPlayerData d){return PLAYER_DATA.get(d.getUniqueId()).getMana();}public double getStamina(vn.svframe.svframelib.api.player.MMOPlayerData d){return PLAYER_DATA.get(d.getUniqueId()).getStamina();}public boolean setMana(vn.svframe.svframelib.api.player.MMOPlayerData d,double v,vn.svframe.svframelib.player.resource.ResourceUpdateReason r){return PLAYER_DATA.get(d.getUniqueId()).setMana(v,r);}public boolean setStamina(vn.svframe.svframelib.api.player.MMOPlayerData d,double v,vn.svframe.svframelib.player.resource.ResourceUpdateReason r){return PLAYER_DATA.get(d.getUniqueId()).setStamina(v,r);}});
ServerLifecycleEvents.SERVER_STARTED.register(s->{PLAYER_DATA.start(s);LOG.info("SVFrameMMO Fabric online; classes="+CLASSES.size()+",attributes="+ATTRIBUTES.size()+",players="+PLAYER_DATA.all().size());});ServerLifecycleEvents.SERVER_STOPPING.register(s->{PLAYER_DATA.save();try{if(profileRegistration!=null)profileRegistration.close();}catch(Exception ignored){}});ServerPlayConnectionEvents.JOIN.register((h,sender,server)->PLAYER_DATA.join(h.player));ServerPlayConnectionEvents.DISCONNECT.register((h,server)->PLAYER_DATA.quit(h.player));ServerTickEvents.END_SERVER_TICK.register(s->{tick++;REGEN.tick(tick);if(config.autosaveSeconds()>0&&tick%(config.autosaveSeconds()*20L)==0)PLAYER_DATA.save();});PlayerAttackEvent.EVENT.register(e->{PLAYER_DATA.get(e.getPlayer()).markCombat();var target=e.getAttack().getTarget();if(target instanceof net.minecraft.server.network.ServerPlayerEntity p)PLAYER_DATA.get(p).markCombat();});}
public static long currentTick(){return tick;}public static SVFrameMMOConfig config(){if(config==null)throw new IllegalStateException("SVFrameMMO not initialized");return config;}public static PlayerDataManager playerData(){return PLAYER_DATA;}public static ClassManager classes(){return CLASSES;}public static AttributeManager attributes(){return ATTRIBUTES;}}
